module kernel_area (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [2:0] n,\n    input wire signed [31:0] x [0:7],\n    input wire signed [31:0] y [0:7],\n    output reg [63:0] area,\n    output reg done\n);\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] FINISH = 2'd1;\n    reg [1:0] state;\n    reg cycle_count;\n\n    reg signed [63:0] sum_comb;\n    integer i;\n\n    always @(*) begin\n        sum_comb = 64'sd0;\n        for (i = 0; i < 8; i = i + 1) begin\n            if (i < n) begin\n                if (i < (n-2'd1)) begin\n                    sum_comb = sum_comb + (x[i] * y[i+1] - x[i+1] * y[i]);\n                end else begin\n                    sum_comb = sum_comb + (x[i] * y[0] - x[0] * y[i]);\n                end\n            end\n        end\n    end\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            area <= 64'd0;\n            done <= 1'b0;\n            cycle_count <= 1'b0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        if (sum_comb < 0) begin\n                            area <= (-sum_comb) >>> 1;\n                        end else begin\n                            area <= sum_comb >>> 1;\n                        end\n                        state <= FINISH;\n                    end\n                end\n                FINISH: begin\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                default: begin\n                    state <= IDLE;\n                end\n            endcase\n        end\n    end\nendmodule